class _RecallClient:
    def __init__(self, *, timeout: bool = False) -> None:
        self.timeout = timeout
        self.paths: list[str] = []
        self.payloads: list[dict] = []

    def __enter__(self) -> "_RecallClient":
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        return False

    def get(self, url: str, **kwargs) -> _Response:
        assert url.endswith("/health")
        return _Response(200, {"ok": True})

    def post(self, url: str, json: dict) -> _Response:
        self.paths.append(url.rsplit("/", 1)[-1])
        self.payloads.append(json)
        if self.timeout:
            raise httpx.ReadTimeout("recall timeout")
        assert url.endswith("/recall")
        return _Response(
            200,
            {
                "found": True,
                "confidence": 0.91,
                "items": [
                    {
                        "_key": "memory:galois:arcos",
                        "scores": {"bm25": 0.8, "dense": 0.7, "graph": 0.4},
                    }
                ],
                "meta": {"took_ms": 12},
                "errors": [],
            },
        )


def test_governed_memory_recall_batches_http_recall_and_records_score_channels(monkeypatch) -> None:
    opportunities = [{"organization": "Galois, Inc.", "screening_interface_profile": {"observed": [], "unknowns": ["n/a"]}}]
    signals = [_galois_relationship_signal()]
    client = _RecallClient()
    monkeypatch.setattr(
        "monitor_opportunities.memory_sync.httpx.Client",
        lambda timeout: client,
    )

    receipt = governed_memory_recall(
        "http://memory.local",
        opportunities=opportunities,
        relationship_signals=signals,
        limit=4,
        k=3,
    )

    assert receipt["schema"] == "monitor_opportunities.governed_memory_recall.v1"
    assert receipt["attempted"] == 4
    assert receipt["succeeded"] == 4
    assert receipt["degraded"] is False
    assert {row["status"] for row in receipt["queries"]} == {"MATCHES"}
    assert all(row["raw_database_fallback"] is False for row in receipt["queries"])
    assert all(row["score_channels"] == {"bm25": True, "dense": True, "graph": True} for row in receipt["queries"])
    assert client.paths == ["recall", "recall", "recall", "recall"]
    assert all(payload["k"] == 3 for payload in client.payloads)


def test_governed_memory_recall_records_timeout_degradation_without_raw_db(monkeypatch) -> None:
    opportunities = [{"organization": "Galois, Inc.", "screening_interface_profile": {"observed": [], "unknowns": ["n/a"]}}]
    signals = [_galois_relationship_signal()]
    client = _RecallClient(timeout=True)
    monkeypatch.setattr(
        "monitor_opportunities.memory_sync.httpx.Client",
        lambda timeout: client,
    )

    receipt = governed_memory_recall(
        "http://memory.local",
        opportunities=opportunities,
        relationship_signals=signals,
        limit=2,
    )

    assert receipt["attempted"] == 2
    assert receipt["succeeded"] == 0
    assert receipt["degraded"] is True
    assert {row["status"] for row in receipt["queries"]} == {"DEGRADED_TIMEOUT"}
    assert all("no raw database fallback" in " ".join(row["limitations"]).lower() for row in receipt["queries"])
    assert client.paths == ["recall", "recall"]


class _HealthFailClient:
    def __enter__(self) -> "_HealthFailClient":
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        return False

    def get(self, url: str, **kwargs) -> _Response:
        raise httpx.ConnectTimeout("health timeout")


class _TimeoutRecallClient:
    def __init__(self) -> None:
        self.calls = 0

    def __enter__(self) -> "_TimeoutRecallClient":
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        return False

    def get(self, url: str, **kwargs) -> _Response:
        assert url.endswith("/health")
        return _Response(200, {"ok": True})

    def post(self, url: str, json: dict) -> _Response:
        self.calls += 1
        raise httpx.ReadTimeout("recall timeout")


class _MixedRecallClient:
    def __init__(self) -> None:
        self.calls = 0

    def __enter__(self) -> "_MixedRecallClient":
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        return False

    def get(self, url: str, **kwargs) -> _Response:
        assert url.endswith("/health")
        return _Response(200, {"ok": True})

    def post(self, url: str, json: dict) -> _Response:
        self.calls += 1
        if self.calls == 2:
            return _Response(
                200,
                {
                    "found": True,
                    "confidence": 0.9,
                    "items": [{"_key": "memory-hit", "scores": {"bm25": 1.0}}],
                    "errors": [],
                    "meta": {"took_ms": 12},
                },
            )
        raise httpx.ReadTimeout("recall timeout")


def test_governed_memory_recall_skips_all_queries_when_healthcheck_fails(monkeypatch) -> None:
    monkeypatch.setattr(
        "monitor_opportunities.memory_sync.httpx.Client",
        lambda timeout: _HealthFailClient(),
    )

    receipt = governed_memory_recall(
        "http://memory.local",
        opportunities=[{"organization": "Galois"}],
        relationship_signals=[],
    )

    assert receipt["degraded"] is True
    assert receipt["attempted"] == 0
    assert receipt["skipped"] == 2
    assert {row["status"] for row in receipt["queries"]} == {"SKIPPED_HEALTHCHECK_FAILED"}
    assert receipt["external_effects"] is False


def test_governed_memory_recall_opens_circuit_after_three_consecutive_timeouts(monkeypatch) -> None:
    client = _TimeoutRecallClient()
    monkeypatch.setattr(
        "monitor_opportunities.memory_sync.httpx.Client",
        lambda timeout: client,
    )

    receipt = governed_memory_recall(
        "http://memory.local",
        opportunities=[{"organization": f"Org {idx}"} for idx in range(5)],
        relationship_signals=[],
        limit=6,
    )

    assert receipt["degraded"] is True
    assert receipt["circuit_open"] is True
    assert receipt["attempted"] == 3
    assert receipt["skipped"] == 3
    assert [row["status"] for row in receipt["queries"][:3]] == ["DEGRADED_TIMEOUT"] * 3
    assert {row["status"] for row in receipt["queries"][3:]} == {"SKIPPED_CIRCUIT_OPEN"}
    assert client.calls == 3
    assert receipt["external_effects"] is False


